from pathlib import Path
import json,hashlib,shutil,xml.etree.ElementTree as E,sys
b=Path(__file__).resolve().parent.parent
run=Path('/tmp/lor-event-detail-rebuild-r1')/(sys.argv[1] if len(sys.argv)>1 else 'Verify01')
for mode in ['Import','EditMode','PlayMode']:
 dest=b/'QA'/run.name/mode;dest.mkdir(parents=True,exist_ok=True)
 for name in ['command.json','unity.log','results.xml']:
  p=run/mode/name
  if p.exists():shutil.copyfile(p,dest/name)
cap=b/'UnityCaptures';cap.mkdir(exist_ok=True)
for p in (run/'EventDetail').glob('*'):shutil.copyfile(p,cap/p.name)
shutil.copyfile('ProjectDocs/AI/EventDetailStyleAlignment/R1/UnityVerification/EventDetail/EventDetail_941x1672_RU.png',b/'QA/PreviousEventDetail.png')
shutil.copyfile('ProjectDocs/AI/EventsReferenceRebuild/TabsAndFooterR4/UnityCaptures/Events_941x1672_RU.png',b/'QA/ApprovedEventsStyle.png')
shutil.copyfile('Assets/LegendsOfRus/Resources/DesignScreens/Events.png',b/'Sources/EventsOriginal.png')
choices=[('UnityCaptures/EventDetail_941x1672_RU.png','Implemented — Russian'),('UnityCaptures/EventDetail_941x1672_EN.png','Implemented — English'),('UnityCaptures/EventDetail_576x1280_safe_RU.png','Narrow phone — Russian'),('UnityCaptures/EventDetail_576x1280_safe_EN.png','Narrow phone — English'),('UnityCaptures/EventDetail_1080x2400_safe_RU.png','Tall phone — safe area'),('UnityCaptures/EventDetail_MaxBalances_RU.png','Maximum balances'),('QA/PreviousEventDetail.png','Previous Event Detail — historical capture'),('QA/ApprovedEventsStyle.png','Approved Events R4 — style context'),('Sources/OriginalEventDetailReference.png','Newly found dedicated Event Detail original'),('Sources/EventsOriginal.png','Events reference — style context only')]
options=''.join(f'<option value="{p}">{label}</option>' for p,label in choices)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event Detail — Reference Rebuild R1</title><style>body{background:#0a101a;color:#eeddb5;font:16px/1.5 system-ui;margin:24px auto;max-width:960px;padding:0 16px}h1{font-size:26px}a{color:#9bcded}select{max-width:100%;padding:10px;background:#14263a;color:#f6e4b6;border:1px solid #90713f;font:inherit}.page{display:block;width:min(100%,471px);height:auto;margin:20px auto;border:1px solid #78603b}.note{color:#c3c9d0}button{font:inherit;padding:8px;background:#213146;color:#ffe8b6;border:1px solid #89704a;cursor:pointer}</style><h1>Event Detail — Reference Rebuild R1</h1><p>Actual Unity page: shared Home header and environment, repaired Events frames, Firebird scenery/glow, separate reward icons and source footer.</p><p class="note">A dedicated Event Detail original was located after this rebuild. This R1 page predates that discovery and adapts Events artwork; it does not match the newly found original. Select the dedicated reference below to inspect it. Participation remains unavailable; dates and reward quantities are unconfirmed.</p><label>View <select id="view">OPTIONS</select></label> <button id="original">Compare with previous</button><img id="page" class="page" src="UnityCaptures/EventDetail_941x1672_RU.png" alt="Selected portrait Event Detail page"><p id="caption" class="note">Actual Unity Play Mode capture; isolated test save and simulated screen/safe area.</p><p><a href="ImplementationReport.md">Implementation and verification</a> · <a href="QA/ReferenceFidelityReview.md">Design adaptation and remaining differences</a></p><script>const picker=document.querySelector('#view'),page=document.querySelector('#page'),caption=document.querySelector('#caption');let previous=picker.value;function show(){page.src=picker.value;caption.textContent=picker.value.includes('OriginalEventDetailReference')?'Dedicated original Event Detail reference, discovered after R1.':picker.value.includes('EventsOriginal')?'Original Events reference — style context only, not a dedicated Event Detail design.':picker.value.includes('PreviousEventDetail')?'Historical Event Detail capture — before this rebuild.':picker.value.includes('ApprovedEventsStyle')?'Events R4 native capture — shared style context.':'Actual Unity Play Mode capture; isolated save and simulated screen/safe area.';}picker.onchange=show;document.querySelector('#original').onclick=()=>{if(picker.value.includes('PreviousEventDetail'))picker.value=previous;else{previous=picker.value;picker.value='QA/PreviousEventDetail.png';}show();};</script></html>'''.replace('OPTIONS',options)
(b/'EventDetail_ReferenceRebuild_R1_Review.html').write_text(html)
before=json.loads((b/'Sources/BeforeAssetsHashes.json').read_text());after={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('Assets').rglob('*') if p.is_file()}
record={'modified':sorted(p for p in before.keys()&after.keys() if before[p]!=after[p]),'added':sorted(after.keys()-before.keys()),'deleted':sorted(before.keys()-after.keys()),'checks':{}}
for mode in ['EditMode','PlayMode']:
 r=E.parse(run/mode/'results.xml').getroot();record['checks'][mode]={k:r.get(k) for k in ['result','passed','failed','skipped','total']}
(b/'QA/ScopeAndVerification.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record,indent=2))
